script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync("Activate skill in the {0} domain?" ,api.state.userSessionDomainDetails.domainName);
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync("You are currently in the {0} domain. Enabling this skill will only enable it for this domain.", api.state.userSessionDomainDetails.domainName);
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync("If you would like to enable it in all domains within the same parent domain, you can select Cancel and change your domain scope. After you have changed your domain scope to the parent domain, then try activating the skill.");
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync("Edit skill in the {0} domain?" ,api.state.userSessionDomainDetails.domainName);
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync("You are currently in the {0} domain. Editing this skill will copy the skill to current domain.", api.state.userSessionDomainDetails.domainName);
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync("If you would like to edit the skill for all domains within the same parent domain, you can select Cancel and change your domain scope. After you have changed your domain scope to the parent domain, then try editing the skill.");
}
